<?php
declare(strict_types=1);
final class TaskOrchestrator{
 public function __construct(private mysqli$db,private TaskRepository$tasks,private TaskEventRepository$events,private ?TaskStateMachine$machine=null,private ?TaskStepRepository$steps=null,private ?TaskExecutionRepository$executions=null,private ?TaskStepStateMachine$stepMachine=null,private ?TaskExecutionStateMachine$executionMachine=null){$this->machine??=new TaskStateMachine();$this->steps??=new TaskStepRepository($db);$this->executions??=new TaskExecutionRepository($db);$this->stepMachine??=new TaskStepStateMachine();$this->executionMachine??=new TaskExecutionStateMachine();}
 public function createTask(int$u,int$session,string$title,string$objective,array$o=[]):array{return$this->tx(function()use($u,$session,$title,$objective,$o){$t=$this->tasks->create(['public_id'=>TaskPublicId::generate(),'user_id'=>$u,'created_by_user_id'=>$u,'project_id'=>$o['project_id']??null,'session_id'=>$session,'origin_message_id'=>$o['origin_message_id']??null,'idempotency_key'=>$o['idempotency_key']??null,'origin_type'=>$o['origin_type']??'manual','title'=>$title,'objective'=>$objective,'status'=>TaskStatus::PENDING,'priority'=>$o['priority']??'normal','max_attempts'=>$o['max_attempts']??3]);$this->events->append(['task_id'=>(int)$t['id_'],'actor_type'=>'user','actor_user_id'=>$u,'event_key'=>'task_created','to_status'=>'pending','summary'=>'Tarea creada.']);return$t;});}
 public function transitionTask(int$id,int$u,string$to,int$lock,string$actor='user',array$fields=[]):array{return$this->tx(function()use($id,$u,$to,$lock,$actor,$fields){$t=$this->tasks->findOwnedById($id,$u)??throw new TaskNotFoundException('not_found');$from=$t['status'];$this->machine->assertTransition($from,$to);$n=$this->tasks->updateStatus($id,$u,$to,$lock,$fields);$this->events->append(['task_id'=>$id,'actor_type'=>$actor,'actor_user_id'=>$actor==='user'?$u:null,'event_key'=>'task_'.$to,'from_status'=>$from,'to_status'=>$to,'summary'=>$fields['event_summary']??'Estado actualizado.']);return$n;});}
 public function requestCancellation(int$id,int$u,int$lock):array{return$this->transitionTask($id,$u,'cancelled',$lock,'user',['cancel_requested_at'=>gmdate('Y-m-d H:i:s.u'),'event_summary'=>'Cancelación solicitada.']);}
 public function retryTask(int$id,int$u,int$lock):array{return$this->tx(function()use($id,$u,$lock){$t=$this->tasks->findOwnedById($id,$u)??throw new TaskNotFoundException('not_found');$this->machine->assertTransition($t['status'],'ready');if((int)$t['attempt_count']>=(int)$t['max_attempts'])throw new TaskTransitionException('attempt_limit');$n=$this->tasks->retry($id,$u,$lock);$this->events->append(['task_id'=>$id,'actor_type'=>'user','actor_user_id'=>$u,'event_key'=>'task_ready','from_status'=>'failed','to_status'=>'ready','summary'=>'Tarea preparada para reintento.','details'=>['attempt_count'=>(int)$n['attempt_count']]]);return$n;});}
 public function beginChatTurn(int$u,int$session,?int$project,int$message,string$key,string$title,string$objective,string$trace,string$model):ChatTaskContext{return$this->tx(function()use($u,$session,$project,$message,$key,$title,$objective,$trace,$model){$task=$this->tasks->findOwnedByIdempotencyKey($u,$key);if(!$task){$task=$this->tasks->create(['public_id'=>TaskPublicId::generate(),'user_id'=>$u,'created_by_user_id'=>$u,'project_id'=>$project,'session_id'=>$session,'origin_message_id'=>$message,'idempotency_key'=>$key,'origin_type'=>'chat','title'=>$title,'objective'=>$objective,'status'=>'pending','priority'=>'normal','max_attempts'=>1]);$this->event((int)$task['id_'],'task_created',null,'pending','Tarea de chat creada.',$u);}$step=$this->steps->findByKey((int)$task['id_'],'respond');if(!$step){$step=$this->steps->createRespond((int)$task['id_']);$this->event((int)$task['id_'],'step_created',null,'pending','Step respond creado.',$u,(int)$step['id_']);}$execution=$this->executions->findByTrace($trace)??$this->executions->findAttempt((int)$step['id_'],1);if(!$execution){$execution=$this->executions->create((int)$task['id_'],(int)$step['id_'],$trace,$model);$this->event((int)$task['id_'],'execution_created',null,'queued','Ejecución creada.',$u,(int)$step['id_'],(int)$execution['id_']);}
 if(in_array($task['status'],['completed','failed','cancelled'],true)){return new ChatTaskContext((int)$task['id_'],(string)$task['public_id'],(int)$step['id_'],(int)$execution['id_'],(string)($execution['trace_id']??$trace),(int)$task['lock_version'],(int)$step['lock_version']);}
 foreach(['ready','running']as$to){if($task['status']===$to)continue;$this->machine->assertTransition($task['status'],$to);$from=$task['status'];$task=$this->tasks->updateStatus((int)$task['id_'],$u,$to,(int)$task['lock_version']);$this->event((int)$task['id_'],'task_'.$to,$from,$to,'Estado de tarea actualizado.',$u);}
 foreach(['ready','running']as$to){if($step['status']===$to)continue;$this->stepMachine->assertTransition($step['status'],$to);$from=$step['status'];$step=$this->steps->updateStatus((int)$step['id_'],$to,(int)$step['lock_version']);$this->event((int)$task['id_'],'step_'.$to,$from,$to,'Estado de step actualizado.',$u,(int)$step['id_']);}
 if($execution['status']==='queued'){$this->executionMachine->assertTransition('queued','running');$execution=$this->executions->updateStatus((int)$execution['id_'],'running',null,$model);$this->event((int)$task['id_'],'execution_started','queued','running','Ejecución iniciada.',$u,(int)$step['id_'],(int)$execution['id_']);}
 return new ChatTaskContext((int)$task['id_'],(string)$task['public_id'],(int)$step['id_'],(int)$execution['id_'],$trace,(int)$task['lock_version'],(int)$step['lock_version']);});}
 public function completeChatTurn(ChatTaskContext$c,int$u,int$message,string$summary,string$model):void{$this->tx(function()use($c,$u,$message,$summary,$model){$execution=$this->executions->findById($c->executionId)??throw new RuntimeException('execution_not_found');if($execution['status']==='running'){$this->executionMachine->assertTransition('running','completed');$this->executions->updateStatus($c->executionId,'completed',null,$model);$this->event($c->taskId,'execution_completed','running','completed','Ejecución completada.',$u,$c->stepId,$c->executionId);}$step=$this->steps->findById($c->stepId)??throw new RuntimeException('step_not_found');if($step['status']==='running'){$this->stepMachine->assertTransition('running','completed');$this->steps->updateStatus($c->stepId,'completed',(int)$step['lock_version']);$this->event($c->taskId,'step_completed','running','completed','Step completado.',$u,$c->stepId);}$task=$this->tasks->findOwnedById($c->taskId,$u)??throw new RuntimeException('task_not_found');if($task['status']==='running'){$this->machine->assertTransition('running','completed');$this->tasks->assignResult($c->taskId,$u,$message,$summary);$this->tasks->updateStatus($c->taskId,$u,'completed',(int)$task['lock_version'],['result_summary'=>$summary]);$this->event($c->taskId,'task_completed','running','completed','Tarea completada.',$u);}});}
 public function failChatTurn(ChatTaskContext$c,int$u,string$error):void{$this->tx(function()use($c,$u,$error){$e=$this->executions->findById($c->executionId);if($e&&$e['status']==='running'){$this->executionMachine->assertTransition('running','failed');$this->executions->updateStatus($c->executionId,'failed',$error);$this->event($c->taskId,'execution_failed','running','failed','Ejecución fallida.',$u,$c->stepId,$c->executionId);}$s=$this->steps->findById($c->stepId);if($s&&$s['status']==='running'){$this->stepMachine->assertTransition('running','failed');$this->steps->updateStatus($c->stepId,'failed',(int)$s['lock_version'],['error_message'=>$error]);$this->event($c->taskId,'step_failed','running','failed','Step fallido.',$u,$c->stepId);}$t=$this->tasks->findOwnedById($c->taskId,$u);if($t&&$t['status']==='running'){$this->machine->assertTransition('running','failed');$this->tasks->updateStatus($c->taskId,$u,'failed',(int)$t['lock_version'],['error_code'=>'chat_pipeline_failed','error_message'=>$error]);$this->event($c->taskId,'task_failed','running','failed','Tarea fallida.',$u);}});}
 private function event(int$task,string$key,?string$from,string$to,string$summary,int$u,?int$step=null,?int$execution=null):void{$this->events->append(['task_id'=>$task,'step_id'=>$step,'execution_id'=>$execution,'actor_type'=>'system','actor_user_id'=>$u,'event_key'=>$key,'from_status'=>$from,'to_status'=>$to,'summary'=>$summary]);}
 private function tx(callable$f){$this->db->begin_transaction();try{$r=$f();$this->db->commit();return$r;}catch(Throwable$e){$this->db->rollback();throw$e;}}
}
